'use strict';
const $ = s => document.querySelector(s);
function regionalPerformance(){return ''}

const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',facilities:'<path d="M3 21V7l9-4 9 4v14H3Z"/><path d="M8 9v2m8-2v2m-8 4v2m8-2v2m-5 4v-5h2v5"/>',alerts:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3h.01"/>',work:'<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 5V3h6v2M9 11h6m-6 5h6"/>',insights:'<path d="m3 17 5-6 4 3 8-10M3 3v18h18"/>',logs:'<path d="M4 3h16v15H8l-4 4V3Z"/><path d="M8 8h8m-8 5h5"/>',home:'<path d="m2 10 10-8 10 8M5 9v12h14V9M9 21v-8h6v8"/>',halls:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M4 8h16M4 15h16M8 5h.01M8 12h.01M8 19h.01"/>',bms:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="12" cy="12" r="5"/><path d="M12 7v5l3 2"/>',mechanical:'<path d="M12 2v5m0 10v5M2 12h5m10 0h5"/><circle cx="12" cy="12" r="7"/><path d="m9 9 6 6m0-6-6 6"/>',electrical:'<path d="m13 2-8 12h6l-1 8 9-13h-6l1-7Z"/>',fire:'<path d="M13 2c1 6-5 7-3 11 2-1 3-3 3-4 7 5 7 13-1 13S1 15 6 9c-1 6 2 7 2 7-2-6 5-8 5-14Z"/>',security:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=n=>`<span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.overview}</svg></span>`;
const C={mint:'#5ce0bc',blue:'#6f98ff',red:'#ff7e86',amber:'#f5bf68',purple:'#ad94f7'};
const sites=[{id:'cairo',name:'5th Settlement Campus',city:'New Cairo',region:'Greater Cairo',lat:30.01,lon:31.48,short:'FST-01',status:'critical',pue:1.42,power:12.8,racks:78,buildings:4,customers:42,alarms:2},{id:'capital',name:'New Administrative Capital Campus',city:'New Capital',region:'Greater Cairo',lat:30.02,lon:31.75,short:'NAC-01',status:'operational',pue:1.26,power:9.6,racks:56,buildings:3,customers:24,alarms:0},{id:'october',name:'6th October Campus',city:'Giza',region:'Greater Cairo',lat:29.95,lon:30.85,short:'GIZ-01',status:'operational',pue:1.31,power:8.4,racks:64,buildings:3,customers:28,alarms:0},{id:'alex',name:'Borg El Arab Campus',city:'Alexandria',region:'Mediterranean',lat:30.91,lon:29.57,short:'ALX-01',status:'operational',pue:1.28,power:7.1,racks:71,buildings:3,customers:31,alarms:0},{id:'suez',name:'Suez Canal Campus',city:'Ismailia',region:'Canal',lat:30.59,lon:32.27,short:'ISM-01',status:'warning',pue:1.51,power:6.2,racks:59,buildings:2,customers:19,alarms:1},{id:'aswan',name:'Aswan Edge Campus',city:'Aswan',region:'Upper Egypt',lat:24.09,lon:32.9,short:'ASW-01',status:'operational',pue:1.38,power:3.9,racks:43,buildings:2,customers:12,alarms:0},{id:'mansoura',name:'Delta Campus',city:'Mansoura',region:'Delta',lat:31.04,lon:31.38,short:'DEL-01',status:'operational',pue:1.34,power:4.2,racks:62,buildings:2,customers:16,alarms:0}];
let saved={};try{saved=JSON.parse(localStorage.getItem('nile-state')||'{}')}catch{}
let state={page:'overview',site:null,building:null,tab:'home',region:'all',query:'',filter:'all',paused:false,heatmap:false,zoom:1,mapX:0,mapY:0,ack:saved.ack||[],work:saved.work||[{id:'WO-1042',title:'Inspect AHU-03 return air sensor',site:'5th Settlement Campus',priority:'High',status:'Open',assignee:'Mechanical team',skill:'HVAC diagnostics'},{id:'WO-1041',title:'UPS-B preventive battery inspection',site:'Suez Canal Campus',priority:'Medium',status:'In progress',assignee:'Electrical team',skill:'UPS maintenance'},{id:'WO-1038',title:'Replace rack inlet probe R-12',site:'5th Settlement Campus',priority:'Low',status:'Completed',assignee:'Facilities team',skill:'Sensor calibration'}],logs:saved.logs||[{text:'Cooling circuit B inspected. AHU-03 sensor verification scheduled; redundant cooling remains available.',author:'Operations team',date:'2026-11-04T14:30:00Z',skill:'HVAC diagnostics'}],tick:0};
const baseAlerts=[{id:'AL-2048',site:'cairo',title:'High rack inlet temperature',asset:'DC-01 · Data Hall A · R-12',system:'halls',severity:'critical',reading:'32.8 °C',threshold:'Above 30 °C',time:'2 min ago'},{id:'AL-2047',site:'cairo',title:'AHU return temperature deviation',asset:'DC-01 · AHU-03',system:'mechanical',severity:'critical',reading:'29.4 °C',threshold:'Above 28 °C',time:'7 min ago'},{id:'AL-2046',site:'suez',title:'UPS battery health declining',asset:'DC-01 · UPS-B',system:'electrical',severity:'warning',reading:'76 %',threshold:'Below 80 %',time:'18 min ago'}];
for(const order of state.work)if(order.site==='New '+'Cairo Campus')order.site='5th Settlement Campus';
let mapFeatures=null,governorateFeatures=[],riverFeatures=[];
function persist(){localStorage.setItem('nile-state',JSON.stringify({ack:state.ack,work:state.work,logs:state.logs}))}
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function status(s){return `<span class="status ${s}">${s==='operational'?'Operational':s==='critical'?'Critical':'Attention'}</span>`}
function scopedSites(){return sites.filter(s=>(!state.site||s.id===state.site)&&(state.region==='all'||s.region===state.region))}
function activeAlerts(){return baseAlerts.filter(a=>scopedSites().some(s=>s.id===a.site))}
function currentSite(){return sites.find(s=>s.id===state.site)||sites[0]}
function spark(seed=0,color=C.mint){let pts=Array.from({length:20},(_,i)=>`${i*6},${28-Math.sin(i*.7+seed)*7-Math.cos(i*1.9+seed)*4}`).join(' ');return `<svg class="spark" viewBox="0 0 115 42" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.6"/></svg>`}
function kpi(label,value,unit,change,detail,seed,color=C.mint){return `<article class="kpi-card"><div class="kpi-top">${label}<span class="kpi-symbol">${['▦','ϟ','◷','◈'][seed%4]}</span></div><div class="kpi-value">${value}<small>${unit}</small></div><div class="kpi-bottom"><span style="color:${color}">${change}</span> ${detail}</div>${spark(seed,color)}</article>`}
function panel(title,sub,body,tools='',cls=''){return `<section class="panel ${cls}"><div class="panel-header"><div class="panel-title">${title}${sub?`<div class="panel-subtitle">${sub}</div>`:''}</div><div class="panel-tools">${tools}</div></div>${body}</section>`}
function lineChart(series=2,kind='power'){let labels=kind==='daily'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['00:00','04:00','08:00','12:00','16:00','20:00'];let paths=[];for(let s=0;s<series;s++){let p=Array.from({length:30},(_,i)=>[35+i*10.55,95-s*29-Math.sin(i*.43+s)*12-Math.cos(i*1.1)*6-i*.45]);paths.push(`<path d="M${p.map(x=>x.join(',')).join('L')}L341,132L35,132Z" fill="${s===0?C.blue:C.mint}" opacity=".05"/><path d="M${p.map(x=>x.join(',')).join('L')}" fill="none" stroke="${s===0?C.blue:C.mint}" stroke-width="2"/>`)}return `<svg class="chart-svg" viewBox="0 0 370 160" role="img" aria-label="Simulated ${kind} trend">${[25,60,95,132].map((y,i)=>`<line class="chart-grid" x1="34" y1="${y}" x2="345" y2="${y}"/><text class="chart-label" x="3" y="${y+3}">${kind==='temperature'?[35,30,25,20][i]:[60,40,20,0][i]}</text>`).join('')}${paths.join('')}${labels.map((l,i)=>`<text class="chart-label" x="${35+i*60}" y="153">${l}</text>`).join('')}</svg>`}
function barChart(){return `<svg class="chart-svg" viewBox="0 0 350 160" role="img" aria-label="Monthly energy consumption and renewable contribution">${[25,60,95,132].map((y,i)=>`<line class="chart-grid" x1="30" y1="${y}" x2="340" y2="${y}"/><text class="chart-label" x="0" y="${y+3}">${[60,40,20,0][i]}</text>`).join('')}${Array.from({length:12},(_,i)=>{let h=54+(i*13%39);return `<rect x="${38+i*25}" y="${132-h}" width="10" height="${h}" rx="2" fill="${C.blue}" opacity="${i===10?1:.7}"/><rect x="${38+i*25}" y="${132-h}" width="10" height="${h*.3}" rx="2" fill="${C.mint}"/><text class="chart-label" x="${37+i*25}" y="152">${'JFMAMJJASOND'[i]}</text>`}).join('')}</svg>`}
function donut(value=72,label='Utilized',color=C.blue){return `<svg class="donut" viewBox="0 0 150 150" role="img" aria-label="${label}: ${value}%"><circle cx="75" cy="75" r="55" stroke="#243345" stroke-width="12" fill="none"/><circle cx="75" cy="75" r="55" stroke="${color}" stroke-width="12" fill="none" stroke-dasharray="${value*3.456} 345.6" transform="rotate(-90 75 75)" stroke-linecap="round"/><text x="75" y="74" text-anchor="middle" fill="#e4edf6" font-size="29">${value}<tspan font-size="13">%</tspan></text><text x="75" y="95" text-anchor="middle" fill="#8399b0" font-size="9">${label}</text></svg>`}
function capacity(){return ['Power','Cooling','Rack space','Network'].map((n,i)=>`<div class="capacity-row"><span>${n}</span><div class="bar-track"><div class="bar-fill" style="width:${[68,57,72,46][i]}%;background:${[C.blue,C.mint,C.purple,C.amber][i]}"></div></div><b>${[68,57,72,46][i]}%</b></div>`).join('')}
function route(page,site=state.site,building=state.building){state.page=page;state.site=site;state.building=building;state.query='';state.filter='all';if(page==='building'&&!state.building)state.building='DC-01';render();window.scrollTo({top:0,behavior:'smooth'})}
function navigation(){let entries=[['overview','Portfolio overview','overview'],['regions','Regional performance','insights'],['facilities','Facilities','facilities'],['alerts','Alarm center','alerts'],['work','Work orders','work'],['insights','Predictive insights','insights'],['logs','Team journal','logs']];$('#main-nav').innerHTML=entries.map(([id,label,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}">${icon(ico)}<span class="nav-text">${label}</span>${id==='alerts'?`<span class="nav-badge">${baseAlerts.filter(a=>!state.ack.includes(a.id)).length}</span>`:''}</button>`).join('');$('#system-nav').innerHTML=[['home','Building overview'],['halls','Data halls'],['bms','BMS / FMS'],['mechanical','Mechanical'],['electrical','Electrical'],['fire','Fire systems'],['security','Physical security']].map(([id,label])=>`<button class="nav-item ${state.page==='building'&&state.tab===id?'active':''}" data-tab="${id}">${icon(id)}<span class="nav-text">${label}</span>${id==='mechanical'?'<span class="nav-badge">1</span>':''}</button>`).join('')}
function breadcrumbs(){let parts=[`<button data-action="reset">Egypt portfolio</button>`];if(state.region!=='all')parts.push(`<button data-action="region">${esc(state.region)}</button>`);if(state.site)parts.push(`<button data-campus="${state.site}">${esc(currentSite().name)}</button>`);if(state.building)parts.push(`<button data-building="${state.building}">${state.building}</button>`);if(state.page==='building')parts.push(`<span>${({home:'Overview',halls:'Data halls',bms:'Building management',mechanical:'Mechanical',electrical:'Electrical',fire:'Fire systems',security:'Physical security'})[state.tab]}</span>`);$('#breadcrumbs').innerHTML=parts.join('<span style="color:#455d73">/</span>')}
function render(){navigation();breadcrumbs();let titles={regions:['EGYPT / REGIONAL OPERATIONS',state.site?currentSite().name+' performance.':'Regional data center performance.','Performance follows the selected location · Simulated operational and cost data.'],overview:[state.region==='all'?'EGYPT / PORTFOLIO':`EGYPT / ${state.region.toUpperCase()}`,'A clear view of every facility.','Monitor performance, trace alerts, and keep your infrastructure moving.'],facilities:['ASSET DIRECTORY','Your infrastructure, connected.','Explore campuses and drill down to every building and system.'],campus:['CAMPUS / SITE OPERATIONS',currentSite().name,'A unified picture of buildings, environment, and operational health.'],building:[`${currentSite().city.toUpperCase()} / ${state.building}`,({home:'Building operations.',halls:'Inside the white space.',bms:'Every system, in context.',mechanical:'Cooling that keeps you running.',electrical:'Power without interruption.',fire:'Prepared for every emergency.',security:'Secure at every entry.'})[state.tab],'Live simulation · Select an asset to inspect its readings and operational status.'],alerts:['EVENT MANAGEMENT','Focus on what needs attention.','Follow each alert from portfolio impact to the source equipment.'],work:['MAINTENANCE','Keep the next issue from happening.','Plan, assign, and track work across your facilities.'],insights:['PREDICTIVE MONITORING','See the signal before the failure.','Illustrative anomaly scenarios · Connect a trained model for real predictions.'],logs:['WORKER COLLABORATION','A shared picture of every shift.','Capture handovers, share observations, and coordinate technical skills.']};let t=titles[state.page]||titles.overview;$('#eyebrow').textContent=t[0];$('#page-title').textContent=t[1];$('#page-description').textContent=t[2];$('#scope-button').textContent='⌖ '+(state.region==='all'?'All locations':state.region);$('#notification-count').textContent=baseAlerts.filter(a=>!state.ack.includes(a.id)).length;$('#content').innerHTML=({regions:regionalPerformance,overview:overview,facilities:facilities,campus:campus,building:building,alerts:alertsPage,work:workPage,insights:insightsPage,logs:logsPage}[state.page]||overview)();updateClock()}
function portfolioKPIs(){let ss=scopedSites(),pue=(ss.reduce((t,s)=>t+s.power,0)/ss.reduce((t,s)=>t+s.power/s.pue,0)).toFixed(2),power=ss.reduce((t,s)=>t+s.power,0).toFixed(1),n=ss.reduce((t,s)=>t+s.buildings,0);return `<div class="kpi-grid">${kpi('Active data centers',n,'buildings',`${ss.length} campuses`,'across Egypt',0)}${kpi('Power usage effectiveness',pue,'PUE','↘ 0.06','vs. previous month',1)}${kpi('Total facility power',power,'MW','↘ 4.2%','vs. previous month',2,C.blue)}${kpi('Service availability','99.98','%','↑ 0.02%','rolling 30 days',3)}</div>`}
function overview(){return portfolioKPIs()+`<div class="overview-middle">${mapPanel()}${healthPanel()}</div><div class="bottom-grid">${panel('Energy performance','Facility consumption over the last 24 hours',`<div class="chart-summary"><strong>${scopedSites().reduce((t,s)=>t+s.power,0).toFixed(1)} <small>MW current load</small></strong><span class="chip green">−4.2% vs. yesterday</span></div><div class="chart-body">${lineChart()}</div><div class="chart-legend"><span><i></i>Facility power</span><span><i class="mint"></i>IT power</span></div>`,'<span class="chip">Today</span>')}${panel('Capacity at a glance','Current use vs. available capacity',`<div class="chart-summary"><strong>72<small>% rack utilization</small></strong><span class="chip">+3.1%</span></div>${capacity()}`)}${panel('Energy mix','A cleaner operational footprint',`<div class="donut-wrap">${donut(32,'Renewable',C.mint)}<div class="donut-key"><p><span><i class="legend-dot"></i>Renewable</span><b>32%</b></p><p><span><i class="legend-dot" style="background:${C.blue}"></i>Utility grid</span><b>64%</b></p><p><span><i class="legend-dot" style="background:${C.amber}"></i>Backup</span><b>4%</b></p></div></div>`)}</div>${facilitiesTable('Campus performance')}`}
function project(lon,lat){return [(lon-23.6)/13*850,(33.1-lat)/12.4*480]}
function geoPath(coords){return coords.map(ring=>ring.map((p,i)=>`${i?'L':'M'}${project(p[0],p[1]).map(v=>v.toFixed(1)).join(',')}`).join('')+'Z').join('')}
function mapLayers(){return governorateFeatures.map(f=>{let polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return polys.map(p=>`<path class="map-border" d="${geoPath(p)}"/>`).join('')}).join('')+riverFeatures.map(f=>{let lines=f.geometry.type==='LineString'?[f.geometry.coordinates]:f.geometry.coordinates;return lines.map(line=>`<polyline class="map-river" points="${line.map(p=>project(...p).join(',')).join(' ')}"/>`).join('')}).join('')}
function mapSVG(){let shapes='';if(mapFeatures){shapes=mapFeatures.map(f=>{let egypt=f.properties.ADM0_A3==='EGY'||f.properties.ADMIN==='Egypt';let polys=f.geometry.type==='Polygon'?[f.geometry.coordinates]:f.geometry.coordinates;return polys.map(p=>`<path class="land ${egypt?'egypt':''}" d="${geoPath(p)}"/>`).join('')}).join('')}else{shapes=`<path class="land" d="M0 0H850V480H0Z"/><path class="land egypt" d="M92 38 130 43 166 51 215 52 263 45 295 37 330 39 366 66 400 73 422 96 459 101 473 80 505 57 554 41 590 55 611 85 622 118 610 148 600 170 577 190 569 219 584 245 603 275 626 308 655 348 687 384 728 411 744 445 92 445Z"/><path fill="#122433" stroke="#314b5b" d="M0 0H850V19L705 20 624 32 590 55 554 41 505 57 473 80 459 101 422 96 400 73 366 66 330 39 295 37 263 45 215 52 166 51 130 43 92 38 0 35Z"/><path fill="#112837" stroke="#355368" d="m502 101 25 33 34 32 23 31 14 26 15 19 12 33 24 41 33 52 44 59 25 53H850V140l-99-62-96 71-41 59-18-19-18-36-24-29-27-35Z"/>`}
let nile=[[31.13,31.42],[31.23,30.05],[31.0,29.3],[30.78,28.4],[30.75,27.8],[31.2,27.1],[31.6,26.8],[31.9,26.5],[32.7,26.1],[32.65,25.7],[32.9,24.09],[32.8,23],[32.7,22.1]].map(p=>project(...p).join(',')).join(' ');let ss=scopedSites();return `<svg viewBox="0 0 850 480" role="img" aria-label="Interactive Egypt campus map"><defs><pattern id="grid" width="52" height="48" patternUnits="userSpaceOnUse"><path d="M52 0H0V48" fill="none" class="map-grid"/></pattern></defs><g transform="translate(${state.mapX} ${state.mapY}) translate(425 240) scale(${state.zoom}) translate(-425 -240)">${shapes}<rect width="850" height="480" fill="url(#grid)" pointer-events="none"/><polyline class="map-river" points="${nile}"/><path class="map-river" d="M499 118 475 86M499 118 511 80"/><text class="map-label country" x="250" y="260">E G Y P T</text><text class="map-label water" x="260" y="25">MEDITERRANEAN SEA</text><text class="map-label water" x="690" y="280" transform="rotate(55 690 280)">RED SEA</text><text class="map-label" x="23" y="250" opacity=".45">LIBYA</text><text class="map-label" x="330" y="471" opacity=".45">SUDAN</text><path class="map-road" d="M390 90 490 120 547 97M490 120 607 350"/>${ss.map((s,i)=>{let [x,y]=project(s.lon,s.lat);if(s.id==='cairo'){x+=9;y+=8}if(s.id==='october'){x-=12;y+=15}let color=s.status==='critical'?C.red:s.status==='warning'?C.amber:C.mint;let labels={cairo:[18,15],october:[-18,27],alex:[-15,-19],suez:[18,-4],mansoura:[0,-21],aswan:[18,4],capital:[18,-12]};let [lx,ly]=labels[s.id];return `<g class="map-pin" tabindex="0" role="button" aria-label="Open ${s.name}, ${s.status}" data-campus="${s.id}" style="color:${color}" transform="translate(${x} ${y})"><circle class="pin-halo" r="${s.status==='critical'?25:19}"/><circle class="pin-core" r="9"/><circle class="pin-center" r="3"/><text class="pin-label" x="${lx}" y="${ly}" text-anchor="${lx<0?'end':'start'}">${s.city}</text></g>`}).join('')}</g></svg>`}
function mapPanel(){return panel('Infrastructure footprint','Six campuses. One connected operational picture.',`<div class="map-wrap" id="map-wrap">${mapSVG()}<div class="map-controls"><button data-zoom="in" aria-label="Zoom in">+</button><button data-zoom="out" aria-label="Zoom out">−</button><button data-zoom="reset" aria-label="Reset map">⌖</button></div><div class="map-caption"><span>30° 02′ N &nbsp; 31° 14′ E</span>${mapFeatures?'Natural Earth · Offline vector map':'Illustrative geography · Download assets for sourced boundaries'}</div></div><div class="map-legend"><span><i class="legend-dot"></i>Operational</span><span><i class="legend-dot" style="background:${C.amber}"></i>Attention</span><span><i class="legend-dot" style="background:${C.red}"></i>Critical</span><span>Click a campus to explore ↗</span></div>`,`<div class="map-tabs"><button class="active" data-action="map">Map view</button><button data-page="facilities">Directory</button></div>`,'map-panel')}
function healthPanel(){let a=activeAlerts();return panel('Portfolio health','All systems, at a glance',`<div class="health-score"><strong>97.4<small>/100</small></strong><span class="chip green">Healthy overall</span></div><div class="health-segments"><span style="width:87%;background:${C.mint}"></span><span style="width:8%;background:${C.amber}"></span><span style="width:5%;background:${C.red}"></span></div><div class="health-detail"><span>Normal systems</span><b>184 / 192</b></div><div class="divider"></div><div class="panel-header" style="padding-bottom:0"><span class="panel-title">Needs your attention</span><span class="chip red">${a.length} active</span></div>${a.slice(0,2).map(x=>`<div class="mini-alert"><span class="alert-icon ${x.severity==='warning'?'warn':''}">!</span><div><strong>${esc(x.title)}</strong><p>${sites.find(s=>s.id===x.site).city} · ${x.asset}<br>${x.time}</p></div></div>`).join('')}<button class="text-button" data-page="alerts">View alarm center <span style="margin-left:10px">↗</span></button>`,'','health-panel')}
function facilitiesTable(title='Facility directory'){let ss=scopedSites().filter(s=>(s.name+' '+s.city).toLowerCase().includes(state.query.toLowerCase())&&(state.filter==='all'||s.status===state.filter));return panel(title,`${ss.length} campuses in current selection`,`${state.page==='overview'?'':`<div class="info-note">All campus names, locations, and readings are demonstration data.</div>`}<table><thead><tr><th>Campus / location</th><th>Status</th><th>PUE</th><th>Facility power</th><th>Rack utilization</th><th>Alarms</th><th></th></tr></thead><tbody>${ss.map(s=>`<tr><td><div class="site-cell"><span class="site-symbol">▥</span><div><strong>${s.name}</strong><small>${s.city}, Egypt · ${s.short}</small></div></div></td><td>${status(s.status)}</td><td>${s.pue.toFixed(2)}</td><td>${s.power.toFixed(1)} <span style="color:#678198">MW</span></td><td><span class="table-meter"><span class="bar-track"><span class="bar-fill" style="width:${s.racks}%;display:block"></span></span>${s.racks}%</span></td><td>${s.alarms?`<span class="chip ${s.status==='critical'?'red':'amber'}">${s.alarms} active</span>`:'<span style="color:#6c8796">—</span>'}</td><td><button class="table-link" data-campus="${s.id}">Explore ↗</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No campuses match your search.</td></tr>'}</tbody></table>`,`<div class="table-controls"><input class="search-box" id="site-search" value="${esc(state.query)}" placeholder="Search campuses…" aria-label="Search campuses"><select id="status-filter" aria-label="Filter status"><option value="all">All statuses</option>${['operational','warning','critical'].map(s=>`<option ${state.filter===s?'selected':''} value="${s}">${s==='warning'?'Attention':s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select></div>`,'table-panel')}
function facilities(){return portfolioKPIs()+facilitiesTable()+`<div class="bottom-grid">${panel('Monthly energy','Consumption and renewable contribution',`<div class="chart-body">${barChart()}</div><div class="chart-legend"><span><i></i>Total energy</span><span><i class="mint"></i>Renewable share</span></div>`)}${panel('Capacity headroom','Remaining infrastructure capacity',capacity())}${panel('Regional footprint','Demonstration portfolio',`<div class="rank-list">${[...new Set(sites.map(s=>s.region))].map(r=>`<div class="rank-row"><span>${r}</span><button class="table-link" data-region="${r}">${sites.filter(s=>s.region===r).length} campus${sites.filter(s=>s.region===r).length>1?'es':''} ↗</button></div>`).join('')}</div>`)}</div>`}
function campusPlan(){let s=currentSite();return `<svg class="floorplan" viewBox="0 0 800 430" role="img" aria-label="Illustrative interactive campus layout"><defs><pattern id="planGrid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" stroke="#243345" fill="none" stroke-width=".4"/></pattern></defs><rect width="800" height="430" fill="url(#planGrid)"/><path d="M45 350V70H745V350H45Z" fill="none" stroke="#2c3c4e" stroke-width="22"/><path d="M45 350V70H745V350H45Z" fill="none" stroke="#42556b" stroke-dasharray="8 8"/><rect class="room" x="95" y="110" width="135" height="70" rx="3"/><text class="plan-label" x="116" y="145">CHILLER PLANT</text><rect class="room" x="290" y="95" width="140" height="55" rx="3"/><text class="plan-label" x="313" y="127">ENERGY CENTER</text>${Array.from({length:s.buildings},(_,i)=>{let x=105+i*153;return `<g class="building-block" tabindex="0" role="button" aria-label="Open building DC-0${i+1}" data-building="DC-0${i+1}"><rect class="plan-building ${i===0&&s.alarms?'plan-alarm':''}" x="${x}" y="215" width="112" height="91" rx="5"/>${Array.from({length:4},(_,j)=>`<rect x="${x+10+j*24}" y="203" width="16" height="12" rx="2" fill="#31495d"/>`).join('')}<text class="plan-label" x="${x+34}" y="254">DC-0${i+1}</text><text class="plan-small" x="${x+25}" y="276">${i===0&&s.alarms?'ALERT ACTIVE':'OPERATIONAL'}</text>${i===0&&s.alarms?`<circle cx="${x+102}" cy="223" r="10" fill="${C.red}"/><text x="${x+99}" y="227" fill="#291a23" font-size="12">!</text>`:''}</g>`}).join('')}<rect class="room" x="590" y="95" width="90" height="60" rx="3"/><text class="plan-label" x="605" y="129">ADMIN</text><rect class="equipment" x="640" y="341" width="55" height="32"/><text class="plan-small" x="642" y="391">GATE A</text><path d="M615 350h-60" stroke="${C.mint}" stroke-width="3"/><text class="plan-small" x="80" y="400">CAMPUS PLAN · ILLUSTRATIVE · SELECT A BUILDING</text><text class="plan-small" x="700" y="30">N ↑</text></svg>`}
function campus(){let s=currentSite();return `<div class="kpi-grid">${kpi('Data center buildings',s.buildings,'buildings','● Connected','all monitored systems',0)}${kpi('Campus PUE',s.pue,'PUE','↘ 0.04','vs. previous month',1)}${kpi('Facility power',s.power,'MW','↓ 3.1%','vs. previous month',2,C.blue)}${kpi('Active customers',s.customers,'tenants','↑ 2','this quarter',3)}</div><div class="split-layout">${panel('Campus layout','Follow alerts directly to the affected building.',campusPlan(),status(s.status))}${panel('Site conditions','External factors and operational status',`<div class="detail-list"><p>Outdoor temperature<strong data-live="outdoor">28.4 °C</strong></p><p>Relative humidity<strong>48 %RH</strong></p><p>Rainfall<strong>0.0 mm</strong></p><p>Utility supply<strong class="positive">Available</strong></p><p>Backup generation<strong>Standby</strong></p><p>Physical access<strong class="positive">Secured</strong></p><p>Current alerts<strong style="color:${s.alarms?C.red:C.mint}">${s.alarms} active</strong></p></div><button class="text-button" data-page="alerts">Review campus alerts ↗</button>`)}</div>${panel('Building performance','Select a building to explore its systems.',`<table><thead><tr><th>Building</th><th>Status</th><th>Temperature</th><th>Humidity</th><th>Rack utilization</th><th></th></tr></thead><tbody>${Array.from({length:s.buildings},(_,i)=>`<tr><td><strong>${s.short} / DC-0${i+1}</strong></td><td>${status(i===0?s.status:'operational')}</td><td>${i===0&&s.alarms?'27.4':'23.6'} °C</td><td>${45+i*2} %RH</td><td>${s.racks-i*7}%</td><td><button class="table-link" data-building="DC-0${i+1}">Open building ↗</button></td></tr>`).join('')}</tbody></table>`,'','table-panel')}`}
const tabNames={home:'Overview',halls:'Data halls',bms:'BMS / FMS',mechanical:'Mechanical',electrical:'Electrical',fire:'Fire systems',security:'Physical security'};
function building(){return `<div class="system-tabs">${Object.entries(tabNames).map(([t,n])=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${n}</button>`).join('')}</div>`+({home:buildingHome,halls:dataHalls,bms:bms,mechanical:mechanical,electrical:electrical,fire:fire,security:security}[state.tab])()}
function buildingKPIs(){return `<div class="kpi-grid">${kpi('Building PUE','1.42','PUE','↘ 0.03','vs. yesterday',1)}${kpi('Facility power','3.20','MW','↘ 2.8%','vs. yesterday',2,C.blue)}${kpi('Average inlet temperature','23.6','°C','● Within range','target: 18–27 °C',0)}${kpi('Rack utilization','78','%','+4 racks','this month',3)}</div>`}
function floorPlan(mode='bms'){return `<svg class="floorplan" viewBox="0 0 800 420" role="img" aria-label="Building floor plan with selectable equipment"><rect x="40" y="30" width="720" height="350" fill="#121f2d" stroke="#526b80" stroke-width="1.5"/>${[['Generator A',60,48,140,65],['UPS-B',215,48,110,65],['AHU-03',340,48,175,65],['Switchgear',535,48,205,65],['Batteries',60,310,140,50],['Control room',215,310,150,50],['Telecom',380,310,160,50],['Entry',560,310,180,50]].map(([n,x,y,w,h])=>`<g data-equipment="${n}" class="building-block" role="button" tabindex="0" aria-label="Inspect ${n}"><rect class="room ${n==='AHU-03'&&mode!=='fire'?'plan-alarm':''}" x="${x}" y="${y}" width="${w}" height="${h}"/><text class="plan-label" x="${x+w/2}" y="${y+h/2+4}" text-anchor="middle">${n}</text></g>`).join('')}${[0,1].map(h=>`<rect class="room" x="${60+h*345}" y="140" width="330" height="150"/><text class="plan-label" x="${225+h*345}" y="164" text-anchor="middle">DATA HALL ${h?'B':'A'}</text>${Array.from({length:9},(_,i)=>`<rect x="${75+h*345+i*34}" y="183" width="22" height="83" rx="2" fill="#20384a" stroke="#3c576c"/>${Array.from({length:5},(_,j)=>`<path d="M${77+h*345+i*34} ${195+j*13}h18" stroke="#4f6c81" stroke-width="2"/>`).join('')}`).join('')}`).join('')}${mode==='fire'?[[80,130],[390,270],[730,135]].map(([x,y],i)=>`<g data-equipment="Fire zone ${i+1}" class="building-block" tabindex="0" role="button"><circle cx="${x}" cy="${y}" r="10" fill="${i===1?C.amber:C.mint}"/><text x="${x-3}" y="${y+4}" fill="#122534" font-size="11">${i+1}</text></g>`).join(''):''}<text class="plan-small" x="45" y="404">GROUND FLOOR · ILLUSTRATIVE PLAN · CLICK EQUIPMENT TO INSPECT</text></svg>`}
function buildingHome(){return buildingKPIs()+`<div class="split-layout">${panel('Building systems overview','Operational layout and equipment locations',floorPlan(),'<span class="chip">Ground floor</span>')}${panel('System health','Status across the selected building',`<div class="rank-list">${Object.entries(tabNames).filter(([t])=>t!=='home').map(([t,n])=>`<div class="rank-row"><span>${n}</span><button class="table-link" data-tab="${t}" style="color:${t==='halls'||t==='mechanical'?C.red:C.mint}">${t==='halls'||t==='mechanical'?'Inspect alert':'Normal'} ↗</button></div>`).join('')}</div>`)}</div><div class="bottom-grid">${panel('Facility vs. IT load','24-hour power demand',`<div class="chart-body">${lineChart()}</div><div class="chart-legend"><span><i></i>Facility load</span><span><i class="mint"></i>IT load</span></div>`)}${panel('Resource capacity','Across the selected building',capacity())}${panel('Cooling efficiency','Current operating performance',`<div class="donut-wrap">${donut(84,'Efficiency',C.purple)}<div class="donut-key"><p>COP <b>5.3</b></p><p>Redundancy <b>N+1</b></p><p>AHUs running <b>7 / 8</b></p></div></div>`)}</div>`}
function dataHalls(){return buildingKPIs()+`<div class="split-layout">${panel('Data Hall A · Rack layout','Select any rack to inspect its environment and load.',`<div class="rack-grid">${Array.from({length:32},(_,i)=>`${i===16?'<div class="rack-aisle">COLD AISLE / CONTAINMENT</div>':''}<button class="rack ${i===11?'critical':i===20?'warning':''}" data-equipment="Rack R-${String(i+1).padStart(2,'0')}" aria-label="Inspect rack R-${i+1}">${Array.from({length:6},()=>`<span style="${state.heatmap?`background:${i===11?'#a7515a':i===20?'#9b7945':'#245955'}`:''}"></span>`).join('')}<label>R-${String(i+1).padStart(2,'0')}</label></button>`).join('')}</div>`,`<button class="heatmap-toggle" data-action="heatmap">${state.heatmap?'Hide':'Show'} thermal overlay</button>`)}${panel('White space conditions','Current data hall readings',`<div class="detail-list"><p>Average inlet<strong>23.6 °C</strong></p><p>Maximum inlet<strong style="color:${C.red}">32.8 °C · R-12</strong></p><p>Relative humidity<strong>46 %RH</strong></p><p>Cold aisle differential<strong>9.2 °C</strong></p><p>Cooling units<strong>4 / 4 available</strong></p><p>Containment<strong class="positive">Sealed</strong></p><p>Water leak detection<strong class="positive">Clear</strong></p></div>`)}</div><div class="bottom-grid">${panel('Temperature trend','Average and maximum rack inlet',`<div class="chart-body">${lineChart(2,'temperature')}</div><div class="chart-legend"><span><i></i>Average inlet</span><span><i class="mint"></i>Maximum inlet</span></div>`)}${panel('Rack capacity','Current occupied rack positions',`<div class="donut-wrap">${donut(78,'Occupied')}<div class="donut-key"><p>Occupied <b>250</b></p><p>Available <b>70</b></p><p>Total <b>320</b></p></div></div>`)}${panel('Hall alarms','Traceable equipment events',`<div class="mini-alert"><span class="alert-icon">!</span><div><strong>R-12 high inlet temperature</strong><p>32.8 °C · threshold 30 °C<br>Inspect containment and cooling supply.</p></div></div><button class="text-button" data-equipment="Rack R-12">Inspect rack ↗</button>`)}</div>`}
function bms(){return `<div class="split-layout">${panel('Building management · Floor plan','Air handling, energy, auxiliary systems, and equipment alerts.',floorPlan())}${panel('Floor performance','Efficiency by floor',`<div class="detail-list">${['Ground floor','First floor','Second floor','Roof plant'].map((f,i)=>`<p>${f}<strong>${[1.42,1.35,1.38,1.29][i]} PUE</strong></p>`).join('')}<p>Building uptime<strong>99.98 %</strong></p><p>Open work orders<strong>${state.work.filter(w=>w.status!=='Completed').length}</strong></p></div>`)}</div><div class="metric-grid">${equipmentCard('Air handling','7 / 8','units active','AHU-03 return air temperature requires inspection.','AHU-03')}${equipmentCard('Water management','86','% tank level','Supply pressure 3.2 bar · No active leak detection.','Water tank')}${equipmentCard('Backup fuel','74','% available','Generator readiness verified · Fuel telemetry simulated.','Generator A')}</div>`}
function equipmentCard(title,value,unit,description,asset){return `<section class="panel equipment-card"><div style="display:flex;justify-content:space-between"><h3>${title}</h3><span class="chip green">Monitored</span></div><div class="reading">${value} <small>${unit}</small></div><p>${description}</p><button class="text-button" style="padding:10px 0 0" data-equipment="${asset}">Inspect equipment ↗</button></section>`}
function mechanical(){return `<div class="kpi-grid">${kpi('Cooling demand','1.84','MW','● Stable','current building load',2,C.blue)}${kpi('Supply air temperature','18.2','°C','● Within range','target: 18–20 °C',0)}${kpi('Cooling COP','5.30','','↑ 0.2','vs. yesterday',3)}${kpi('AHU-03 return air','29.4','°C','↑ Above limit','threshold: 28 °C',1,C.red)}</div>${panel('AHU-03 · Air handling schematic','Select a sensor or component to inspect its readings.',`<svg class="floorplan" viewBox="0 0 950 360" role="img" aria-label="Air handling unit schematic"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#6d94a8"/></marker></defs><path d="M70 105H870M70 250H870M370 105V250" fill="none" stroke="#455f74" stroke-width="28"/><path d="M70 105H870M70 250H870" fill="none" stroke="#142736" stroke-width="22"/><path d="M180 105h80M620 105h80M180 250h80M620 250h80" stroke="#6d94a8" stroke-width="2" marker-end="url(#arrow)"/>${[[320,250,'Filter'],[470,250,'Cooling coil'],[600,250,'Supply fan'],[600,105,'Return fan']].map(([x,y,n])=>`<g data-equipment="${n}" class="building-block" role="button" tabindex="0"><rect x="${x-30}" y="${y-40}" width="60" height="80" rx="4" class="equipment"/><text class="plan-small" x="${x}" y="${y+65}" text-anchor="middle">${n}</text>${n.includes('fan')?`<circle cx="${x}" cy="${y}" r="22" fill="none" stroke="#7c9caf"/><path d="m${x-14} ${y-14} 28 28m0-28-28 28" stroke="#7c9caf"/>`:`<path d="M${x-18} ${y-27}v54m12-54v54m12-54v54m12-54v54" stroke="#658fa7"/>`}</g>`).join('')}<g data-equipment="AHU-03" role="button" tabindex="0" class="building-block"><circle cx="780" cy="105" r="22" fill="#422d3b" stroke="${C.red}"/><text x="780" y="109" text-anchor="middle" fill="${C.red}" font-size="10">TT</text><text x="780" y="64" text-anchor="middle" fill="${C.red}" font-size="15">29.4 °C</text></g><text class="plan-label" x="80" y="64">Return / exhaust air</text><text class="plan-label" x="80" y="308">Fresh / supply air</text><text x="780" y="296" fill="${C.mint}" font-size="15">18.2 °C</text></svg>`,'<span class="chip red">1 critical event</span>')}<div class="bottom-grid" style="margin-top:20px">${panel('Cooling performance','Supply and return trend',`<div class="chart-body">${lineChart(2,'temperature')}</div>`)}${panel('Cooling capacity','Load against installed capacity',`<div class="donut-wrap">${donut(57,'Cooling load',C.mint)}<div class="donut-key"><p>Current <b>1.84 MW</b></p><p>Installed <b>3.20 MW</b></p></div></div>`)}${panel('Maintenance recommendation','Illustrative rule-based advisory',`<div class="mini-alert"><span class="alert-icon warn">↗</span><div><strong>Inspect AHU-03 return sensor</strong><p>Temperature remains above the configured limit. Verify the sensor and airflow.</p></div></div><button class="text-button" data-action="new-work">Create work order ↗</button>`)}</div>`}
function electrical(){return `<div class="kpi-grid">${kpi('Incoming utility power','3.20','MW','● Grid available','primary supply A',2,C.blue)}${kpi('IT power','2.25','MW','70.4%','of facility demand',0)}${kpi('UPS efficiency','96.8','%','↑ 0.4%','vs. previous month',3)}${kpi('Generator readiness','100','%','● Standby','4 / 4 units ready',1)}</div><div class="split-layout">${panel('Power distribution','Illustrative single-line supply overview',`<svg class="floorplan" viewBox="0 0 780 340" role="img" aria-label="Electrical power distribution"><path d="M100 75H680M200 75V170H580V75M390 170V270M200 170V270M580 170V270" stroke="#6289a2" stroke-width="3" fill="none"/>${[[80,40,'UTILITY A'],[560,40,'GENERATOR A'],[140,140,'UPS-A'],[520,140,'UPS-B'],[140,250,'HALL A'],[330,250,'COOLING'],[520,250,'HALL B']].map(([x,y,n])=>`<g data-equipment="${n}" class="building-block" tabindex="0" role="button"><rect x="${x}" y="${y}" width="120" height="55" rx="5" class="equipment"/><circle cx="${x+105}" cy="${y+10}" r="3" fill="${n==='UPS-B'?C.amber:C.mint}"/><text class="plan-label" text-anchor="middle" x="${x+60}" y="${y+31}">${n}</text></g>`).join('')}</svg>`)}${panel('Supply resilience','Redundancy and backup capacity',`<div class="detail-list"><p>Grid supply<strong class="positive">Online</strong></p><p>UPS-A<strong class="positive">Healthy</strong></p><p>UPS-B battery health<strong style="color:${C.amber}">76 % · Attention</strong></p><p>Battery autonomy<strong>18 minutes</strong></p><p>Diesel level<strong>74 %</strong></p><p>Generator mode<strong>Auto / Standby</strong></p><p>Redundancy<strong>N+1</strong></p></div>`)}</div><div class="bottom-grid">${panel('Power demand','Facility vs. IT demand',`<div class="chart-body">${lineChart()}</div>`)}${panel('Monthly energy','Electricity consumption',`<div class="chart-body">${barChart()}</div>`)}${panel('Power source mix','Current consumption',`<div class="donut-wrap">${donut(32,'Renewable',C.mint)}<div class="donut-key"><p>Grid <b>64%</b></p><p>Renewable <b>32%</b></p><p>Backup <b>4%</b></p></div></div>`)}</div>`}
function fire(){return `<div class="insight-banner"><span style="font-size:24px;color:${C.mint}">◈</span><div><strong>Fire response systems available</strong><p>No fire emergency in this simulated scenario. One detector has a scheduled maintenance advisory.</p></div><span class="chip green" style="margin-left:auto">SYSTEM NORMAL</span></div><div class="split-layout">${panel('Fire detection zones','Zone overlays and response equipment',floorPlan('fire'))}${panel('Response readiness','Read-only monitoring',`<div class="detail-list"><p>Fire alarm panel<strong class="positive">Normal</strong></p><p>Smoke detectors<strong>95 / 96 online</strong></p><p>Suppression system<strong class="positive">Ready</strong></p><p>Fire pump<strong>Standby</strong></p><p>Header pressure<strong>8.2 bar</strong></p><p>Emergency exits<strong class="positive">Clear</strong></p><p>Valves monitored<strong>12 / 12 open</strong></p></div>`)}</div><div class="metric-grid">${equipmentCard('Zone 1 · Plant room','32','detectors online','Smoke and heat detectors monitored. No active fire event.','Fire zone 1')}${equipmentCard('Zone 2 · Data halls','47 / 48','detectors online','Detector SD-042 offline for scheduled inspection.','Fire zone 2')}${equipmentCard('Zone 3 · Support areas','16','detectors online','Exit routes and suppression readiness monitored.','Fire zone 3')}</div>`}
function cameraScene(i){return `<svg viewBox="0 0 400 220" aria-label="Illustrative offline camera placeholder"><rect width="400" height="220" fill="#172633"/><path d="M0 220 150 60H250L400 220Z" fill="#334753"/><path d="M0 0 150 60V220H0ZM400 0 250 60V220H400Z" fill="#10212c"/>${Array.from({length:6},(_,j)=>`<path d="M${j*24} 0V220M${400-j*24} 0V220" stroke="#3c5563" opacity=".7"/>${Array.from({length:6},(_,k)=>`<rect x="${j*24+4}" y="${k*30+9}" width="15" height="15" fill="#243c4c"/><circle cx="${j*24+15}" cy="${k*30+14}" r="1.5" fill="#68baa4"/><rect x="${400-j*24-20}" y="${k*30+9}" width="15" height="15" fill="#243c4c"/>`).join('')}`).join('')}<path d="M180 70 160 220M220 70l20 150" stroke="#59717c"/><rect x="174" y="13" width="53" height="7" fill="#b4c6c9" opacity=".4"/><text x="200" y="120" text-anchor="middle" font-size="11" fill="#7a9ba8">CAMERA PLACEHOLDER</text><text x="200" y="137" text-anchor="middle" font-size="8" fill="#7a9ba8">No live video source configured</text></svg>`}
function security(){return `<div class="kpi-grid">${kpi('Cameras available','23 / 24','','1 offline','maintenance scheduled',0,C.amber)}${kpi('Access points secured','12 / 12','','● Secured','all monitored doors',1)}${kpi('Authorized entries today','142','entries','↑ 12','vs. yesterday',2,C.blue)}${kpi('Security incidents','0','active','● Clear','current building',3)}</div><div class="filter-row"><span class="chip">CAMERA GRID</span><span class="chip amber">Illustrative placeholders · No live CCTV connected</span></div><div class="cctv-grid">${['Data Hall A · North aisle','Data Hall A · South aisle','Data Hall B · Entry','Main gate · Entry lane','Control room corridor','Service entrance'].map((n,i)=>`<section class="camera">${i===5?'<div class="camera-offline"><span style="font-size:24px">⊘</span><span>Camera unavailable</span><small>Scheduled maintenance</small></div>':cameraScene(i)}<span class="camera-label">CAM-0${i+1} · ${n}</span><span class="camera-status" style="${i===5?'color:'+C.amber:''}">${i===5?'OFFLINE':'DEMO'}</span><span class="camera-mode">${i===5?'No signal':'Local vector placeholder'}</span></section>`).join('')}</div>${panel('Entry system status','Physical access monitoring',`<table><thead><tr><th>Access point</th><th>Door state</th><th>Controller</th><th>Last event</th></tr></thead><tbody>${['Main gate','Data Hall A','Data Hall B','Control room'].map((n,i)=>`<tr><td>${n}</td><td>${status('operational')}</td><td>Online</td><td>${[2,7,12,18][i]} min ago · Authorized access</td></tr>`).join('')}</tbody></table>`,'','table-panel')}`}
function alertsPage(){let aa=activeAlerts().filter(a=>state.filter==='all'||a.severity===state.filter);return `<div class="kpi-grid">${kpi('Active events',activeAlerts().length,'events','● Monitoring','simulated sources',0,C.blue)}${kpi('Critical alerts',activeAlerts().filter(a=>a.severity==='critical').length,'alerts','Needs review','equipment attention',1,C.red)}${kpi('Warning alerts',activeAlerts().filter(a=>a.severity==='warning').length,'alerts','Early warning','maintenance attention',2,C.amber)}${kpi('Acknowledged',state.ack.length,'events','Saved locally','operator acknowledgment',3)}</div>${panel('Alarm center','Acknowledging an alarm records review; the source condition stays active.',`<table><thead><tr><th>Event / equipment</th><th>Severity</th><th>Reading</th><th>Detected</th><th>Review status</th><th></th></tr></thead><tbody>${aa.map(a=>`<tr><td><div class="site-cell"><div><strong>${a.title}</strong><small>${sites.find(s=>s.id===a.site).name} · ${a.asset}</small></div></div></td><td>${status(a.severity)}</td><td>${a.reading}<div style="font-size:8px;color:#7b92a8;margin-top:5px">${a.threshold}</div></td><td>${a.time}</td><td>${state.ack.includes(a.id)?'<span class="chip green">Acknowledged</span>':`<button class="button small" data-ack="${a.id}">Acknowledge</button>`}</td><td><button class="table-link" data-alert="${a.id}">Trace source ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No events match this selection.</td></tr>'}</tbody></table>`,`<select id="alert-filter" aria-label="Filter severity"><option value="all">All severities</option><option value="critical" ${state.filter==='critical'?'selected':''}>Critical</option><option value="warning" ${state.filter==='warning'?'selected':''}>Warning</option></select>`,'table-panel')}`}
function workPage(){return `<div class="filter-row"><button class="button primary" data-action="new-work">+ Create work order</button><span class="chip">${state.work.filter(w=>w.status!=='Completed').length} open / in progress</span><span class="chip">Saved on this browser</span></div><div class="work-grid">${['Open','In progress','Completed'].map(st=>`<section class="work-column"><h3>${st}<span class="chip">${state.work.filter(w=>w.status===st).length}</span></h3>${state.work.filter(w=>w.status===st).map(w=>`<article class="work-card"><span class="chip ${w.priority==='High'?'red':w.priority==='Medium'?'amber':''}">${esc(w.priority)} priority</span><h4>${esc(w.title)}</h4><p>${esc(w.site)}<br>Skill: ${esc(w.skill||'General maintenance')}</p><div class="work-meta"><span>${esc(w.id)}</span><span>${esc(w.assignee)}</span></div>${st!=='Completed'?`<button class="text-button" style="padding:15px 0 0" data-work="${esc(w.id)}">${st==='Open'?'Start work':'Mark completed'} →</button>`:'<p class="positive">✓ Work completed</p>'}</article>`).join('')||'<div class="empty">No work orders</div>'}</section>`).join('')}</div>`}
function insightsPage(){return `<div class="insight-banner"><span style="font-size:24px;color:${C.mint}">⌁</span><div><strong>Predictive monitoring · Demonstration mode</strong><p>These are predefined illustrative scenarios, not output from a trained predictive model. Model integration is a future step.</p></div><span class="chip">RULE-BASED DEMO</span></div><div class="metric-grid">${equipmentCard('AHU-03 · Thermal anomaly','+4.1','°C deviation','Return temperature has exceeded the expected operating envelope. Inspect airflow and sensor calibration.','AHU-03')}${equipmentCard('UPS-B · Battery degradation','76','% battery health','Battery health is below the demonstration advisory threshold. Schedule a battery capacity test.','UPS-B')}${equipmentCard('Rack R-12 · Hot spot','32.8','°C inlet','Localized temperature exceeds the hall limit. Check blanking panels and nearby cooling distribution.','Rack R-12')}</div><div class="split-layout">${panel('Observed signal vs. baseline','Illustrative temperature anomaly scenario',`<div class="chart-body">${lineChart(2,'temperature')}</div><div class="chart-legend"><span><i></i>Observed signal</span><span><i class="mint"></i>Expected baseline</span></div>`)}${panel('Recommended next steps','Operator review before action',`<div class="detail-list"><p>1. Verify sensor readings<strong>Required</strong></p><p>2. Review equipment trend<strong>Required</strong></p><p>3. Inspect affected asset<strong>Recommended</strong></p></div><button class="text-button" data-action="new-work">Create inspection work order ↗</button>`)}</div>`}
function logsPage(){return `<div class="filter-row"><button class="button primary" data-action="new-log">+ Add shift observation</button><span class="chip">Local collaboration prototype</span></div><div class="split-layout">${panel('Shift journal','Shared observations, handovers, and maintenance notes.',`<div class="notes-list">${state.logs.slice().reverse().map(l=>`<article class="note"><small>${esc(l.author)} · ${new Date(l.date).toLocaleString('en-GB')} · ${esc(l.skill||'Operations')}</small>${esc(l.text)}</article>`).join('')}</div>`)}${panel('Team skills','Example maintenance capabilities',`<div class="detail-list"><p>Mechanical team<strong>HVAC diagnostics</strong></p><p>Electrical team<strong>UPS maintenance</strong></p><p>Facilities team<strong>Sensor calibration</strong></p><p>Security team<strong>Access systems</strong></p></div><p class="info-note">This prototype stores records in this browser. Shared users and a central backend are not connected yet.</p>`)}</div>`}
function openDrawer(html){$('#drawer').innerHTML=`<button class="drawer-close" data-action="close-drawer" aria-label="Close panel">✕</button>${html}`;$('#drawer').hidden=false;$('#drawer-overlay').hidden=false;$('#drawer-close')?.focus();$('#drawer .drawer-close').focus()}
function closeDrawer(){$('#drawer').hidden=true;$('#drawer-overlay').hidden=true}
function equipmentDrawer(name){let hot=/R-12|AHU-03/i.test(name),ups=/UPS-B/i.test(name);openDrawer(`<div class="eyebrow">ASSET INSPECTOR</div><h2>${esc(name)}</h2><p>${esc(currentSite().name)} / ${state.building||'DC-01'}<br>Demonstration equipment telemetry</p>${status(hot?'critical':ups?'warning':'operational')}<div class="detail-list" style="padding:0"><p>Current temperature<strong>${hot?'29.4':'23.6'} °C</strong></p><p>Power demand<strong>${ups?'420':'18.2'} kW</strong></p><p>Relative humidity<strong>46 %RH</strong></p><p>Telemetry source<strong>Local simulator</strong></p><p>Connection<strong>Available</strong></p></div><h3>Recent trend</h3>${lineChart(1,'temperature')}<h3>Operating note</h3><p>${hot?'Reading is above the configured demonstration threshold. Verify the equipment and sensor before corrective action.':ups?'Battery health is below the advisory threshold. Plan a capacity inspection.':'Operating within its demonstration range. No corrective action suggested.'}</p><button class="button primary" data-action="new-work">+ Create inspection work order</button>`)}
function scopeDrawer(){openDrawer(`<div class="eyebrow">LOCATION FILTER</div><h2>Choose your operational scope.</h2><p>KPIs, facility lists, and map markers update together.</p><div class="rank-list" style="padding:0"><div class="rank-row"><span>All Egypt</span><button class="table-link" data-region="all">Select →</button></div>${[...new Set(sites.map(s=>s.region))].map(r=>`<div class="rank-row"><span>${r}</span><button class="table-link" data-region="${r}">Select →</button></div>`).join('')}</div>`)}
function offlineGuide(){openDrawer(`<div class="eyebrow">OFFLINE SETUP</div><h2>Built to run locally.</h2><p>The interface, charts, floor plans, rack layouts, and camera placeholders are bundled locally. No CDN or external font is needed.</p><h3>1. Download geographic assets once</h3><p>Run these commands from the project folder with an internet connection:</p><pre>node scripts/download-assets.mjs</pre><p>This downloads Natural Earth country boundaries, governorates, and rivers, then creates a compact local Egypt map.</p><h3>2. Start the local dashboard</h3><pre>node scripts/serve.mjs</pre><p>Open <strong>http://localhost:8080</strong>. Once assets are downloaded, the local dashboard needs no internet connection.</p><h3>About the visuals</h3><p>Campus plans, equipment diagrams, and camera placeholders are original SVG graphics included in the app. Live camera footage and satellite imagery are not bundled. The map displays illustrative fallback geography until the asset download succeeds.</p><p>Natural Earth geographic data is public domain. Boundaries are for visualization and are not a survey or navigation source.</p>`)}
function newWork(){openDrawer(`<div class="eyebrow">MAINTENANCE</div><h2>Create a work order.</h2><form id="work-form"><label for="work-title">Task description</label><input id="work-title" name="title" required maxlength="160" placeholder="Inspect AHU-03 return air sensor"><label for="work-site">Campus</label><select id="work-site" name="site">${sites.map(s=>`<option ${s.id===state.site?'selected':''}>${s.name}</option>`).join('')}</select><label for="work-priority">Priority</label><select name="priority" id="work-priority"><option>Medium</option><option>High</option><option>Low</option></select><label for="work-team">Assigned team</label><select name="assignee" id="work-team"><option>Mechanical team</option><option>Electrical team</option><option>Facilities team</option><option>Security team</option></select><label for="work-skill">Required skill</label><input name="skill" id="work-skill" placeholder="HVAC diagnostics" required maxlength="80"><button type="submit" class="button primary" style="margin-top:15px">Create work order</button></form>`)}
function newLog(){openDrawer(`<div class="eyebrow">TEAM JOURNAL</div><h2>Capture a shift observation.</h2><form id="log-form"><label for="log-author">Author / team</label><input id="log-author" name="author" required value="Operations team" maxlength="80"><label for="log-skill">Related skill</label><input id="log-skill" name="skill" placeholder="HVAC diagnostics" maxlength="80"><label for="log-text">Observation</label><textarea id="log-text" name="text" required maxlength="2000" placeholder="Record equipment observations and handover notes…"></textarea><button class="button primary" type="submit">Save observation</button></form>`)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
function exportReport(){let rows=[['Campus','City','Status','PUE','Facility power (MW)','Rack utilization (%)','Active alarms'],...scopedSites().map(s=>[s.name,s.city,s.status,s.pue,s.power,s.racks,s.alarms])];let csv='Demo data - Schneider Electric Unified Operations Center report\r\n'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));let a=document.createElement('a');a.href=url;a.download='schneider-portfolio-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Current portfolio report exported as CSV')}
function updateClock(){let time=new Date().toLocaleTimeString('en-GB',{timeZone:'Africa/Cairo',hour:'2-digit',minute:'2-digit',second:'2-digit'});$('#footer-clock').textContent=time+' EET';$('#updated-time').textContent=(state.paused?'Paused at ':'Updated ')+time;$('#live-label').textContent=state.paused?'Simulation paused':'Simulation running';$('#pause-button').textContent=state.paused?'▶':'Ⅱ';$('#pause-button').setAttribute('aria-label',state.paused?'Resume simulation':'Pause simulation')}
document.addEventListener('click',e=>{let t=e.target.closest('button,[data-campus],[data-building],[data-equipment]');if(!t)return;let d=t.dataset;if(d.page){route(d.page);closeDrawer()}if(d.campus){state.tab='home';route('campus',d.campus,null);closeDrawer()}if(d.building){state.tab='home';route('building',state.site||sites[0].id,d.building);closeDrawer()}if(d.tab){state.tab=d.tab;route('building',state.site||sites[0].id,state.building||'DC-01');closeDrawer()}if(d.equipment)equipmentDrawer(d.equipment);if(d.region){state.region=d.region;state.site=null;state.building=null;route('overview',null,null);closeDrawer()}if(d.zoom){state.zoom=d.zoom==='reset'?1:Math.max(1,Math.min(4,state.zoom+(d.zoom==='in'?.4:-.4)));if(d.zoom==='reset'){state.mapX=0;state.mapY=0}$('#map-wrap').querySelector('svg').outerHTML=mapSVG()}if(d.ack){state.ack.push(d.ack);persist();render();toast('Alarm acknowledged. Source condition remains active.')}if(d.alert){let a=baseAlerts.find(a=>a.id===d.alert);state.tab=a.system;state.region='all';route('building',a.site,'DC-01');equipmentDrawer(a.system==='halls'?'Rack R-12':a.system==='electrical'?'UPS-B':'AHU-03')}if(d.work){let w=state.work.find(w=>w.id===d.work);w.status=w.status==='Open'?'In progress':'Completed';persist();render();toast('Work order updated')}if(d.action){let a=d.action;if(a==='reset'){state.region='all';route('overview',null,null)}if(a==='region')route('overview',null,null);if(a==='close-drawer')closeDrawer();if(a==='heatmap'){state.heatmap=!state.heatmap;render()}if(a==='new-work')newWork();if(a==='new-log')newLog()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Enter'&&e.target.matches('g[data-campus],g[data-building],g[data-equipment]'))e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));if(e.key==='Tab'&&!$('#drawer').hidden){let items=Array.from($('#drawer').querySelectorAll('button,input,select,textarea,a')).filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus()}}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'||e.target.id==='alert-filter'){state.filter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.id==='site-search'){state.query=e.target.value;let pos=e.target.selectionStart;render();$('#site-search').focus();$('#site-search').setSelectionRange(pos,pos)}});
document.addEventListener('submit',e=>{if(e.target.id==='work-form'){e.preventDefault();let f=new FormData(e.target);state.work.push({id:'WO-'+Date.now().toString().slice(-7),title:f.get('title').trim(),site:f.get('site'),priority:f.get('priority'),assignee:f.get('assignee'),skill:f.get('skill').trim(),status:'Open'});persist();closeDrawer();route('work');toast('Work order created and saved locally')}if(e.target.id==='log-form'){e.preventDefault();let f=new FormData(e.target);state.logs.push({author:f.get('author').trim(),text:f.get('text').trim(),skill:f.get('skill').trim(),date:new Date().toISOString()});persist();closeDrawer();route('logs');toast('Shift observation saved locally')}});
$('#scope-button').onclick=scopeDrawer;$('#offline-button').onclick=offlineGuide;$('#export-button').onclick=exportReport;$('#notifications-button').onclick=()=>route('alerts');$('#pause-button').onclick=()=>{state.paused=!state.paused;updateClock()};$('#drawer-overlay').onclick=closeDrawer;$('.brand').onclick=e=>{e.preventDefault();state.region='all';route('overview',null,null)};
let drag=null;document.addEventListener('pointerdown',e=>{if(e.target.closest('#map-wrap')&&!e.target.closest('button,.map-pin'))drag={x:e.clientX,y:e.clientY,mx:state.mapX,my:state.mapY}});document.addEventListener('pointermove',e=>{if(drag){state.mapX=drag.mx+(e.clientX-drag.x);state.mapY=drag.my+(e.clientY-drag.y);let el=$('#map-wrap svg');if(el)el.outerHTML=mapSVG()}});document.addEventListener('pointerup',()=>{drag=null});
const baseMapSVG=mapSVG;
mapSVG=()=>baseMapSVG().replace('<rect width="850" height="480" fill="url(#grid)"',mapLayers()+'<rect width="850" height="480" fill="url(#grid)"');
render();
for(const [file,set] of [['egypt-governorates.geojson',v=>{governorateFeatures=v}],['egypt-rivers.geojson',v=>{riverFeatures=v}]])fetch('assets/'+file).then(r=>r.ok?r.json():Promise.reject()).then(d=>{set(d.features);if(state.page==='overview')render()}).catch(()=>{});
fetch('assets/egypt-map.geojson').then(r=>{if(!r.ok)throw Error();return r.json()}).then(d=>{mapFeatures=d.features;if(state.page==='overview')render()}).catch(()=>fetch('assets/countries.geojson').then(r=>r.ok?r.json():Promise.reject()).then(d=>{mapFeatures=d.features.filter(f=>['EGY','LBY','SDN','SAU','ISR','JOR'].includes(f.properties.ADM0_A3));if(state.page==='overview')render()}).catch(()=>{}));
setInterval(()=>{if(!state.paused){state.tick++;updateClock();let n=$('[data-live="outdoor"]');if(n)n.textContent=(28.4+Math.sin(state.tick*.3)*.2).toFixed(1)+' °C';document.querySelectorAll('.spark polyline').forEach((el,i)=>el.setAttribute('points',Array.from({length:20},(_,j)=>`${j*6},${28-Math.sin(j*.7+i+state.tick*.13)*7-Math.cos(j*1.9+i)*4}`).join(' '))) }},3000);
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('sw.js').catch(()=>{});
